using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace EFCoreBasicsDemo
{
    // 实体类
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public bool IsActive { get; set; } = true;

        public ICollection<Order> Orders { get; set; } = new List<Order>();
    }

    public class Order
    {
        public int Id { get; set; }
        public string ProductName { get; set; } = string.Empty;
        public decimal Price { get; set; }
        public int Quantity { get; set; }
        public DateTime OrderDate { get; set; } = DateTime.UtcNow;

        public int UserId { get; set; }
        public User User { get; set; } = null!;
    }

    // DbContext
    public class AppDbContext : DbContext
    {
        public DbSet<User> Users => Set<User>();
        public DbSet<Order> Orders => Set<Order>();

        public AppDbContext(DbContextOptions<AppDbContext> options)
            : base(options) { }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<User>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.Id).UseIdentityColumn();
                entity.Property(e => e.Name).IsRequired().HasMaxLength(100);
                entity.Property(e => e.Email).HasMaxLength(200);
                entity.HasIndex(e => e.Email).IsUnique();
                entity.Property(e => e.CreatedAt).HasDefaultValueSql("GETUTCDATE()");
                entity.HasQueryFilter(e => e.IsActive); // 全局软删除过滤器
            });

            modelBuilder.Entity<Order>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.ProductName).IsRequired().HasMaxLength(200);
                entity.Property(e => e.Price).HasColumnType("decimal(18,2)");
                entity.HasOne(e => e.User)
                    .WithMany(u => u.Orders)
                    .HasForeignKey(e => e.UserId)
                    .OnDelete(DeleteBehavior.Cascade);
            });

            modelBuilder.Entity<User>().HasData(
                new User { Id = 1, Name = "Alice", Email = "alice@example.com" },
                new User { Id = 2, Name = "Bob", Email = "bob@example.com" }
            );
        }
    }

    public static class Demo
    {
        public static async Task RunAsync()
        {
            var services = new ServiceCollection()
                .AddDbContext<AppDbContext>(options =>
                    options.UseInMemoryDatabase("demo")
                        .EnableSensitiveDataLogging()
                        .LogTo(Console.WriteLine, LogLevel.Information))
                .BuildServiceProvider();

            await using var scope = services.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

            // 确保数据库创建（生产环境用 MigrateAsync）
            await db.Database.EnsureCreatedAsync();

            // --- 创建 ---
            var user = new User { Name = "Charlie", Email = "charlie@example.com" };
            db.Users.Add(user);
            await db.SaveChangesAsync();
            Console.WriteLine($"Created user Id={user.Id}");

            // --- 读取（Tracking） ---
            var tracked = await db.Users.FirstAsync(u => u.Id == user.Id);
            tracked.Name = "Charlie Updated";
            await db.SaveChangesAsync(); // UPDATE 只改 Name

            // --- 读取（AsNoTracking） ---
            var readOnly = await db.Users
                .AsNoTracking()
                .Select(u => new { u.Id, u.Name, u.Email })
                .ToListAsync();
            Console.WriteLine($"Read-only count={readOnly.Count}");

            // --- Include 预加载关联数据 ---
            var userWithOrders = await db.Users
                .Include(u => u.Orders)
                .FirstAsync(u => u.Id == user.Id);
            Console.WriteLine($"User {userWithOrders.Name} has {userWithOrders.Orders.Count} orders");

            // --- 删除 ---
            db.Users.Remove(user);
            await db.SaveChangesAsync();
            Console.WriteLine("Deleted.");
        }
    }
}
